import {EQUIPMENT,MATERIALS} from './equipment-catalog.js';
import {eligibility} from './experiment-definitions.js';
export const escapeText=v=>String(v).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
export function requirementDetails(player,e){const r=eligibility(player,e.id);return `<h3>${escapeText(e.name)}</h3><p>${escapeText(e.objective)}</p><p><strong>${r.label}</strong>${r.completed&&!r.available?' · restock requirements still apply':''}</p><h4>Reusable equipment</h4><ul>${Object.entries(e.equipment).map(([id,n])=>`<li>${EQUIPMENT[id].name} × ${n} · owned ${player.equipment[id]||0}${r.missingEquipment[id]?' · missing '+r.missingEquipment[id]:''}</li>`).join('')}</ul><h4>Consumable supplies</h4><ul>${Object.entries(e.materials).map(([id,n])=>`<li>${MATERIALS[id].name} × ${n} · owned ${player.materials[id]||0}${r.missingMaterials[id]?' · missing '+r.missingMaterials[id]:''}</li>`).join('')}</ul>${r.prerequisites.length?'<p>Prerequisites: '+r.prerequisites.map(escapeText).join(', ')+'</p>':''}<p>${e.assemblies.map(escapeText).join(' ')}</p>${e.facilities?.length?'<p>Provided facilities / bundled parts: '+e.facilities.map(escapeText).join('; ')+'</p>':''}`;}
